1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	const FREE_TYPES = 3;
8	const BASE_SCORE = 2;
9	const POINTS_PER_EXTRA_TYPE = 2;
10	
11	const countTypesSeenBySphinx = (army: Card[], sphinxIndex: number): number =>
12	  new Set(
13	    army
14	      .filter((_card, index) => index !== sphinxIndex)
15	      .map((card) => card.monster),
16	  ).size;
17	
18	const scoreSphinx = (army: Card[], sphinxIndex: number): number => {
19	  const typeCount = countTypesSeenBySphinx(army, sphinxIndex);
20	  if (typeCount <= FREE_TYPES) return BASE_SCORE;
21	
22	  const extraTypes = typeCount - FREE_TYPES;
23	  return 1 + POINTS_PER_EXTRA_TYPE * extraTypes;
24	};
25	
26	export const scoreArmy = (army: Card[]): number =>
27	  army.reduce(
28	    (total, card, index) =>
29	      card.monster === SPHINX ? total + scoreSphinx(army, index) : total,
30	    0,
31	  );
